#include <bits/stdc++.h>
using namespace std;

bool solve(vector<vector<int>> graph, int m) {
    // Write your solution here
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    vector<string> lines;
    string line;
    while (getline(cin, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        lines.push_back(line);
    }
    size_t pos = 0;
    int graphLen = stoi(lines[pos++]);
    vector<vector<int>> graph(graphLen);
    for (int i = 0; i < graphLen; i++) {
        istringstream iss(lines[pos++]);
        int v;
        while (iss >> v) graph[i].push_back(v);
    }
    int m = stoi(lines[pos++]);
    bool result = solve(graph, m);
    cout << (result ? "true" : "false") << "\n";
    return 0;
}

