import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {
    static int solve(int n, int[][] edges) {
        // Write your solution here
        return 0;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) lines.add(line);
        int pos = 0;
        int n = Integer.parseInt(lines.get(pos++).trim());
        int edgesLen = Integer.parseInt(lines.get(pos++).trim());
        int[][] edges = new int[edgesLen][];
        for (int i = 0; i < edgesLen; i++) {
            StringTokenizer st = new StringTokenizer(lines.get(pos++));
            edges[i] = new int[st.countTokens()];
            for (int j = 0; j < edges[i].length; j++) edges[i][j] = Integer.parseInt(st.nextToken());
        }
        int result = solve(n, edges);
        System.out.println(result);
    }
}

